/**
 * 启用辅助嗅探功能后根据次函数返回的值识别地址是否为视频，返回true/false
 * @param url
 */
function isVideo(url){
    let t = 0;
    let is_video;
    if(rule.isVideo &&rule.isVideo.trim()){
        is_video = rule.isVideo.trim();
    }
    if(is_video.startsWith('js:')){
        is_video = is_video.replace('js:','');
        t = 1;
    }
    let isVideoObj = {
        url:url,
        isVideo:is_video,
        t:t,
    };
    let result = isVideoParse(isVideoObj);
    if(result){
        log('成功执行辅助嗅探规则并检测到视频地址:\n'+rule.isVideo);
    }
    return result
}

function DRPY(){//导出函数
    return {
        init: init,
        home: home,
        homeVod: homeVod,
        category: category,
        detail: detail,
        play: play,
        search: search,
        proxy:proxy,
        sniffer:sniffer,
        isVideo:isVideo
    }
}

